package com.agacostays.payment.client;
import com.agacostays.payment.dto.response.BillingResponse; import com.agacostays.payment.exception.BusinessRuleException; import tools.jackson.databind.JsonNode; import org.springframework.beans.factory.annotation.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.math.BigDecimal;
@Component public class BillingServiceClient { private final RestClient client; public BillingServiceClient(RestClient.Builder b,@Value("${services.billing.base-url}")String url){client=b.baseUrl(url).build();} public BillingResponse getFinalBill(Long bookingId){try{JsonNode n=client.get().uri("/api/billing/my-bill/{bookingId}",bookingId).retrieve().body(JsonNode.class);return new BillingResponse(bookingId,longV(n,"branchId"),longV(n,"customerId"),amount(n),n.path("paymentStatus").asText(null));}catch(Exception e){throw new BusinessRuleException("Billing service unavailable or final bill not found");}} private Long longV(JsonNode n,String k){return n.path(k).isNumber()?n.get(k).longValue():null;} private BigDecimal amount(JsonNode n){for(String k:new String[]{"finalAmount","amount","payableAmount"})if(n.path(k).isNumber())return n.get(k).decimalValue();return BigDecimal.ZERO;} }
